"""Parvoz IQ — qo'lda yozilgan matnli savollar (docs/IQ-REJA.md §8).

Har daraja: 7 ta so'z munosabati (VERBAL) va 7 ta mantiq (LOGIC) savoli.
Har savol uch tilda TABIIY yozilgan (so'zma-so'z tarjima emas), madaniyatga
bog'liq bo'lmagan tushunchalar. `c` — dizayn murakkabligi (1..4.5), `answer` —
to'g'ri variant indeksi (generator variantlarni aralashtiradi).
"""


def T(uz, ru, en):
    return {"uz": uz, "ru": ru, "en": en}


def Q(c, rule, stem, options, answer=0):
    return {"c": c, "rule": rule, "stem": stem, "options": options, "answer": answer}


REL = T("Munosabatni toping:\n", "Найдите связь:\n", "Find the relation:\n")
ODD = T("Qaysi biri ortiqcha?", "Что лишнее?", "Which one does not belong?")


def rel(c, uz, ru, en, options):
    return Q(c, "analogy", T(REL["uz"] + uz, REL["ru"] + ru, REL["en"] + en), options)


def odd(c, options):
    return Q(c, "odd_one_out", ODD, options)


